window.VEHICLE_HISTORY={"iv:germ_pzkpfw_iv_ausf_c":{"mfr":"Krupp","mfrSource":"wiki","by":"Krupp-Gruson, Magdeburg","prod":"Oct 1938 – Aug 1939","built":"140","text":"Krupp designed the Panzer IV as the support tank of the panzer division: its short 7.5 cm gun fired high-explosive shells at guns and strongpoints while the lighter Panzer III fought tanks. The C was the first version built in quantity, with a better engine and a protected coaxial machine gun; its armour only kept out rifle-calibre fire.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_iv_ausf_c","src":[["Wikipedia · Panzer IV","https://en.wikipedia.org/wiki/Panzer_IV"]]},"iv:germ_pzkpfw_iv_ausf_e":{"mfr":"Krupp","mfrSource":"wiki","by":"Krupp-Gruson, Magdeburg","prod":"Oct 1940 – Apr 1941","built":"206","text":"Ordered after the Polish campaign, the E answered complaints about thin armour with 50 mm on the hull front (30 mm plus an added 30 mm plate on the superstructure), a new cupola and a stowage bin on the turret rear. It still carried the short 7.5 cm KwK 37 for infantry support.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_iv_ausf_e","src":[["Wikipedia · Panzer IV","https://en.wikipedia.org/wiki/Panzer_IV"]]},"iv:germ_panzerbefelhswagen_iv_ausf_j":{"mfr":"Krupp","mfrSource":"wiki","by":"Nibelungenwerk (new builds); refurbished chassis","prod":"1944","built":"105 (17 new, 88 converted)","text":"A command tank for panzer battalion and regiment staffs, built on the Ausf. J. It kept the long 7.5 cm gun but gave up some ammunition for extra radios, a generator and additional periscopes, so commanders could stay in the fight while leading.","wiki":"https://wiki.warthunder.com/unit/germ_panzerbefelhswagen_iv_ausf_j","src":[["Wikipedia · Panzer IV","https://en.wikipedia.org/wiki/Panzer_IV"]]},"iv:f1":{"mfr":"Krupp","mfrSource":"wiki","by":"Krupp-Gruson, Vomag, Nibelungenwerk","prod":"Apr 1941 – Mar 1942","built":"471","text":"The F replaced bolted-on appliqué with single 50 mm plates on the hull and turret front and got wider tracks. It was the last Panzer IV built with the short 7.5 cm gun; after the invasion of the Soviet Union showed it could not deal with the T-34 and KV, the design was re-armed.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_iv_ausf_f","src":[["Wikipedia · Panzer IV","https://en.wikipedia.org/wiki/Panzer_IV"]]},"iv:f2":{"mfr":"Krupp","mfrSource":"wiki","by":"Krupp-Gruson, Vomag, Nibelungenwerk","prod":"Mar – Jul 1942","built":"about 200 (including converted F1s)","text":"The F2 put the long 7.5 cm KwK 40 L/43 into the Panzer IV, turning the support tank into an anti-tank weapon that could defeat the T-34 at normal combat ranges. The designation was short-lived: from mid-1942 these tanks were simply called Ausf. G.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_iv_ausf_f2","src":[["Wikipedia · Panzer IV","https://en.wikipedia.org/wiki/Panzer_IV"]]},"iv:g":{"mfr":"Krupp","mfrSource":"wiki","by":"Krupp-Gruson, Vomag, Nibelungenwerk","prod":"Mar 1942 – Jun 1943","built":"1,927","text":"The G continued the long-gun Panzer IV and, from 1943, received an extra 30 mm plate on the hull front and the longer L/48 gun on late vehicles. It fought in North Africa and on the Eastern Front and became the backbone of many panzer divisions as Panzer III production ran down.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_iv_ausf_g","src":[["Wikipedia · Panzer IV","https://en.wikipedia.org/wiki/Panzer_IV"]]},"iv:h":{"mfr":"Krupp","mfrSource":"wiki","by":"Krupp-Gruson, Vomag, Nibelungenwerk","prod":"Jun 1943 – Feb 1944","built":"about 2,324","text":"The H was the most numerous long-gun Panzer IV up to that point: 80 mm single-plate frontal armour, the L/48 gun, Schürzen side skirts against anti-tank rifles and Zimmerit paste against magnetic mines. It served on every front and was the panzer division's workhorse alongside the Panther.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_iv_ausf_h","src":[["Wikipedia · Panzer IV","https://en.wikipedia.org/wiki/Panzer_IV"]]},"iv:j":{"mfr":"Krupp","mfrSource":"wiki","by":"Nibelungenwerk, St. Valentin (with Vomag early on)","prod":"Feb 1944 – Apr 1945","built":"about 3,160","text":"The final Panzer IV was simplified for wartime production: the auxiliary engine for powered turret traverse was deleted for a larger fuel tank, and many fittings were reduced. Late tanks had wire-mesh skirts and fewer return rollers. It was built mainly at the Nibelungenwerk in Austria.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_iv_ausf_j","src":[["Wikipedia · Panzer IV","https://en.wikipedia.org/wiki/Panzer_IV"]]},"panther:d":{"mfr":"MAN","mfrSource":"wiki","by":"MAN, Daimler-Benz, MNH, Henschel","prod":"Jan – Sep 1943","built":"842","text":"MAN's design won the 1942 competition for a tank to answer the T-34, combining sloped armour with the long 7.5 cm KwK 42 L/70. The D was the first production version and was rushed into service at Kursk in July 1943, where mechanical breakdowns cost more Panthers than enemy fire.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_V_ausf_d_panther","src":[["Wikipedia · Panther tank","https://en.wikipedia.org/wiki/Panther_tank"]]},"panther:a":{"mfr":"MAN","mfrSource":"wiki","by":"MAN, Daimler-Benz, MNH, Demag","prod":"Aug 1943 – Aug 1944","built":"about 2,200","text":"The A fixed many of the D's teething troubles and introduced a cast commander's cupola with periscopes and a ball-mounted hull machine gun. It was the Panther that fought most of 1944, in Normandy and on the Eastern Front.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_V_ausf_a_panther","src":[["Wikipedia · Panther tank","https://en.wikipedia.org/wiki/Panther_tank"]]},"panther:g":{"mfr":"MAN","mfrSource":"wiki","by":"MAN, Daimler-Benz, MNH","prod":"Mar 1944 – Apr 1945","built":"about 2,961","text":"The G was the most produced Panther. Its redesigned hull had one-piece, more steeply angled side plates and no driver's vision port in the glacis; some late tanks had the chin mantlet to stop shots deflecting into the hull roof.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_V_ausf_g_panther","src":[["Wikipedia · Panther tank","https://en.wikipedia.org/wiki/Panther_tank"]]},"panther:f":{"mfr":"MAN","mfrSource":"wiki","by":"Daimler-Benz (planned); hulls also at Ruhrstahl-Hattingen","prod":"planned for April 1945","built":"none completed","text":"The F would have used the narrow Schmalturm turret with a stereoscopic rangefinder and thicker hull roof armour. Some hulls and turrets were being built at Daimler-Benz and Ruhrstahl when the war ended; there is no evidence a complete Ausf. F saw service.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_v_ausf_f_panther","src":[["Wikipedia · Panther tank","https://en.wikipedia.org/wiki/Panther_tank"]]},"panther:germ_pzkpfw_v_ersatz_m10":{"mfr":"MAN","mfrSource":"wiki","by":"Converted by Panzer-Brigade 150","prod":"Dec 1944","built":"5","text":"For Operation Greif in the Ardennes offensive, Panzer-Brigade 150 disguised Panther Ausf. G tanks with sheet-metal panels and US markings to look like American M10 tank destroyers. They were meant to seize Meuse bridges behind the lines; the plan failed and the vehicles were lost near Malmedy.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_v_ersatz_m10","src":[["Wikipedia · Panther tank","https://en.wikipedia.org/wiki/Panther_tank"]]},"tiger:h1":{"mfr":"Henschel","mfrSource":"wiki","by":"Henschel, Kassel (turret design by Krupp)","prod":"Aug 1942 – Aug 1944 (all Tiger I)","built":"1,347 (all Tiger I)","text":"Henschel's heavy tank combined 100 mm frontal armour with the 8.8 cm KwK 36, derived from the Flak gun, and outclassed every Allied tank in 1942–43. Early tanks, the original Ausf. H1 designation, had rubber-tyred road wheels, deep-fording equipment and the drum-shaped cupola.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_VI_ausf_h1_tiger","src":[["Wikipedia · Tiger I","https://en.wikipedia.org/wiki/Tiger_I"]]},"tiger:e":{"mfr":"Henschel","mfrSource":"wiki","by":"Henschel, Kassel","prod":"Aug 1942 – Aug 1944 (all Tiger I)","built":"1,347 (all Tiger I)","text":"From 1943 the Tiger was renamed Ausf. E and kept evolving: the fording kit was dropped, a cast periscope cupola was fitted, Zimmerit was applied and, in 1944, steel-rimmed road wheels replaced the rubber-tyred ones. Production ended in August 1944 in favour of the Tiger II.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_vi_ausf_e_tiger","src":[["Wikipedia · Tiger I","https://en.wikipedia.org/wiki/Tiger_I"]]},"tiger2:pre":{"mfr":"Henschel","mfrSource":"wiki","by":"Henschel (hull), Krupp (turret)","prod":"1944","built":"50","text":"The first 50 Tiger IIs carried the rounded turret Krupp had designed for Porsche's rival VK 45.02 (P). Its curved front and lower-front shot trap led to its replacement, and these tanks are often (wrongly) called Porsche Tigers.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_VI_ausf_b_tiger_IIp","src":[["Wikipedia · Tiger II","https://en.wikipedia.org/wiki/Tiger_II"]]},"tiger2:h":{"mfr":"Henschel","mfrSource":"wiki","by":"Henschel (hull), Krupp (turret)","prod":"1944 – 1945","built":"about 442 (of 492 Tiger IIs)","text":"The production turret had a flat 180 mm front and room for more ammunition. With the long 8.8 cm KwK 43 L/71 and heavily sloped armour it was nearly immune from the front, but it was heavy, thirsty and built in small numbers late in the war.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_VI_ausf_b_tiger_IIh","src":[["Wikipedia · Tiger II","https://en.wikipedia.org/wiki/Tiger_II"]]},"jagdtiger:porsche":{"mfr":"Henschel","mfrSource":"wiki","by":"Nibelungenwerk (Steyr-Daimler-Puch)","prod":"1944","built":"11","text":"The Jagdtiger mounted the 12.8 cm PaK 44 in a fixed casemate on a lengthened Tiger II hull, the heaviest armoured vehicle to see service in the war. The first chassis used Porsche's longitudinal torsion-bar suspension with eight road wheels per side, which was cheaper to build.","wiki":"https://wiki.warthunder.com/unit/germ_panzerjager_tiger","src":[["Wikipedia · Jagdtiger","https://en.wikipedia.org/wiki/Jagdtiger"]]},"jagdtiger:henschel":{"mfr":"Henschel","mfrSource":"wiki","by":"Nibelungenwerk (Steyr-Daimler-Puch)","prod":"1944 – 1945","built":"70–88 in total","text":"Most Jagdtigers used the Henschel interleaved suspension of the Tiger II. Its 250 mm casemate front and 12.8 cm gun were formidable, but only two heavy anti-tank battalions received it and many were abandoned after breakdowns or fuel shortages.","wiki":"https://wiki.warthunder.com/unit/germ_panzerjager_tiger","src":[["Wikipedia · Jagdtiger","https://en.wikipedia.org/wiki/Jagdtiger"]]},"sturmtiger:prototype":{"mfr":"Alkett","mfrSource":"wiki","by":"Alkett","prod":"Oct 1943","built":"1","text":"Alkett built the prototype on a Tiger I chassis and showed it to Hitler in October 1943. Born from the experience of street fighting at Stalingrad, it mounted a 38 cm rocket-assisted mortar originally developed for the navy.","wiki":"https://wiki.warthunder.com/unit/germ_sturmmorser_sturmtiger","src":[["Wikipedia · Sturmtiger","https://en.wikipedia.org/wiki/Sturmtiger"]]},"sturmtiger:production":{"mfr":"Alkett","mfrSource":"wiki","by":"Alkett (converted from rebuilt Tiger I)","prod":"Aug 1944 – Jan 1945","built":"18 including the prototype","text":"Production vehicles were converted from damaged Tiger Is returned for repair. The 38 cm RW 61 fired a 350 kg projectile against buildings and bunkers; just 14 rounds were carried. They served in three companies in the West in 1944–45.","wiki":"https://wiki.warthunder.com/unit/germ_sturmmorser_sturmtiger","src":[["Wikipedia · Sturmtiger","https://en.wikipedia.org/wiki/Sturmtiger"]]},"leopard1:a0":{"mfr":"Krauss-Maffei","mfrSource":"wiki","by":"Krauss-Maffei (prime), designed by a Porsche-led team","prod":"from 1965","built":"6,485 Leopard 1 of all types worldwide","text":"West Germany's first post-war tank put mobility and firepower ahead of armour: the British L7 105 mm gun and a 830 PS MTU engine on a 40-tonne chassis. The first series tank was handed over in September 1965, and the design became a European standard.","wiki":"https://wiki.warthunder.com/unit/germ_leopard_I","src":[["Wikipedia · Leopard 1","https://en.wikipedia.org/wiki/Leopard_1"]]},"leopard1:a1":{"mfr":"Krauss-Maffei","mfrSource":"wiki","by":"Krauss-Maffei","prod":"upgrade from 1970","built":"","text":"The A1 programme added a two-axis gun stabiliser, a thermal sleeve on the barrel, rubber side skirts and new tracks. From 1975 the A1A1 also received bolted-on spaced armour on the cast turret.","wiki":"https://wiki.warthunder.com/unit/germ_leopard_I_a1","src":[["Wikipedia · Leopard 1","https://en.wikipedia.org/wiki/Leopard_1"]]},"leopard1:a5":{"mfr":"Krauss-Maffei","mfrSource":"wiki","by":"Krupp MaK conversions","prod":"first delivered Dec 1986","built":"1,225 converted from 1A1A1","text":"The A5 gave the Leopard 1 a fire-control system derived from the Leopard 2, with the EMES 18 sight, thermal imaging and laser rangefinder. The turret was prepared to take a 120 mm gun, although that was never adopted.","wiki":"https://wiki.warthunder.com/unit/germ_leopard_1a5","src":[["Wikipedia · Leopard 1","https://en.wikipedia.org/wiki/Leopard_1"]]},"leopard1:germ_leopard_c2_mexas":{"mfr":"Krauss-Maffei","mfrSource":"wiki","by":"Canadian upgrade with surplus German 1A5 turrets; IBD MEXAS armour","prod":"C2 from 1999; MEXAS 2006","built":"66 upgraded to C2","text":"Canada rebuilt its Leopard C1 tanks as C2s using surplus German 1A5 turrets, the first entering service in 1999. In 2006 the tanks sent to Kandahar received IBD's MEXAS add-on composite armour, which gives the turret and hull their slab-sided look.","wiki":"https://wiki.warthunder.com/unit/germ_leopard_c2_mexas","src":[["Wikipedia · Leopard 1","https://en.wikipedia.org/wiki/Leopard_1"]]},"flakpanzer:gepard":{"mfr":"Krauss-Maffei","mfrSource":"wiki","by":"Krauss-Maffei; turret by Oerlikon-Contraves and Siemens","prod":"delivered from Dec 1976","built":"420 for Germany (plus 95 Netherlands, 55 Belgium)","text":"The Gepard put two 35 mm Oerlikon cannons, a search radar and a tracking radar on a Leopard 1 hull, giving armoured units their own all-weather air defence. It served the Bundeswehr until 2010 and was later supplied to Ukraine.","wiki":"https://wiki.warthunder.com/unit/germ_flakpz_I_Gepard","src":[["Wikipedia · Flakpanzer Gepard","https://en.wikipedia.org/wiki/Flakpanzer_Gepard"]]},"flakpanzer:germ_flakpz_1a2_gepard":{"mfr":"Krauss-Maffei","mfrSource":"wiki","by":"Krauss-Maffei Wegmann upgrade","prod":"late 1990s","built":"about 220 modernised","text":"The 1A2 modernisation gave the Gepard digital fire control, a new radar processor and improved ammunition. A twin Stinger missile fit was trialled but not bought; the Ozelot took that role instead.","wiki":"https://wiki.warthunder.com/unit/germ_flakpz_1a2_gepard","src":[["Wikipedia · Flakpanzer Gepard","https://en.wikipedia.org/wiki/Flakpanzer_Gepard"]]},"raketenjagdpanzer:rakjpz1":{"mfr":"Rheinstahl","mfrSource":"wiki","by":"Hanomag and Henschel (HS.30 chassis)","prod":"1961 – 1962","built":"","text":"The Bundeswehr's first missile tank destroyer used the HS.30 infantry carrier chassis and French SS.11 wire-guided missiles. It was a stop-gap that showed the value of guided missiles before the purpose-built Raketenjagdpanzer 2 arrived.","wiki":"https://wiki.warthunder.com/unit/germ_raketenjagdpanzer_2","src":[["Wikipedia (de) · Raketenjagdpanzer 2","https://de.wikipedia.org/wiki/Raketenjagdpanzer_2"],["Wikipedia · Kanonenjagdpanzer","https://en.wikipedia.org/wiki/Kanonenjagdpanzer"]]},"raketenjagdpanzer:rakjpz2":{"mfr":"Rheinstahl","mfrSource":"wiki","by":"Hanomag and Henschel (Rheinstahl)","prod":"1967 – 1968","built":"316","text":"Built on the same chassis as the Kanonenjagdpanzer, the Raketenjagdpanzer 2 carried SS.11 missiles fired from two elevating launch rails. Missiles were reloaded from inside under armour.","wiki":"https://wiki.warthunder.com/unit/germ_raketenjagdpanzer_2","src":[["Wikipedia (de) · Raketenjagdpanzer 2","https://de.wikipedia.org/wiki/Raketenjagdpanzer_2"],["Wikipedia · Kanonenjagdpanzer","https://en.wikipedia.org/wiki/Kanonenjagdpanzer"]]},"raketenjagdpanzer:jaguar1":{"mfr":"Rheinstahl","mfrSource":"wiki","by":"Thyssen-Henschel conversion","prod":"1978 – 1982","built":"316 converted","text":"All Raketenjagdpanzer 2 were rebuilt to Jaguar 1 standard with the Euromissile HOT system and extra spaced armour on the hull front, greatly improving range and hit probability.","wiki":"https://wiki.warthunder.com/unit/germ_raketenjagdpanzer_2_hot","src":[["Wikipedia (de) · Raketenjagdpanzer 2","https://de.wikipedia.org/wiki/Raketenjagdpanzer_2"],["Wikipedia · Kanonenjagdpanzer","https://en.wikipedia.org/wiki/Kanonenjagdpanzer"]]},"raketenjagdpanzer:germ_jaguar_2":{"mfr":"Rheinstahl","mfrSource":"wiki","by":"Conversion of Kanonenjagdpanzer","prod":"1983 – 1985","built":"163 converted","text":"When the 90 mm gun of the Kanonenjagdpanzer became obsolete, the vehicles were converted into missile carriers with a roof-mounted TOW launcher and added armour, serving until the 1990s.","wiki":"https://wiki.warthunder.com/unit/germ_jaguar_2","src":[["Wikipedia (de) · Raketenjagdpanzer 2","https://de.wikipedia.org/wiki/Raketenjagdpanzer_2"],["Wikipedia · Kanonenjagdpanzer","https://en.wikipedia.org/wiki/Kanonenjagdpanzer"]]},"marder:a3":{"mfr":"Thyssen-Henschel","mfrSource":"wiki","by":"Thyssen-Henschel (upgrade)","prod":"1988 – 1998","built":"about 2,100 planned","text":"Rheinstahl's Marder, delivered from 1971, was the West's first true infantry fighting vehicle, letting troops fight from a protected vehicle alongside the Leopard. The 1A3 added heavy bolted armour against 30 mm fire, raising weight to about 35 tonnes.","wiki":"https://wiki.warthunder.com/unit/germ_marder_1a3","src":[["Wikipedia · Marder (IFV)","https://en.wikipedia.org/wiki/Marder_(IFV)"]]},"marder:a5":{"mfr":"Thyssen-Henschel","mfrSource":"wiki","by":"Conversion of Marder 1A3","prod":"2003 – 2004","built":"74 converted","text":"The 1A5 added belly armour against mines and roadside bombs to 1A3s for missions such as Afghanistan, where Marders served into the 2010s.","wiki":"https://wiki.warthunder.com/unit/germ_marder_1a3","src":[["Wikipedia · Marder (IFV)","https://en.wikipedia.org/wiki/Marder_(IFV)"]]},"marder:germ_marder_1a1":{"mfr":"Thyssen-Henschel","mfrSource":"wiki","by":"Rheinstahl (later Thyssen-Henschel)","prod":"upgrade 1979 – 1982","built":"350 to A1(–) standard","text":"The A1 upgrade gave the Marder dual-feed for its 20 mm cannon, image-intensifier night sights and a MILAN launcher. The A1(–) version lacked the thermal pointer fitted to the A1(+).","wiki":"https://wiki.warthunder.com/unit/germ_marder_1a1","src":[["Wikipedia · Marder (IFV)","https://en.wikipedia.org/wiki/Marder_(IFV)"]]},"flak_early:germ_flakpanzer_i_ausf_a":{"mfr":"Krupp","mfrSource":"wiki","by":"Stoewer (conversion)","prod":"1941","built":"24","text":"Twenty-four Panzer I Ausf. A were converted to carry a 2 cm Flak 38 in an open hull. All went to Flak-Bataillon 614, which fought in southern Russia and was destroyed at Stalingrad.","wiki":"https://wiki.warthunder.com/unit/germ_flakpanzer_i_ausf_a","src":[]},"flak_early:germ_flakpanzer_38t_gepard":{"mfr":"ČKD / BMM","mfrSource":"wiki","by":"BMM (ČKD), Prague","prod":"1943 – 1944","built":"about 140","text":"A stop-gap tracked anti-aircraft vehicle on the Panzer 38(t) chassis, with a 2 cm Flak 38 in an open, armoured fighting compartment at the rear.","wiki":"https://wiki.warthunder.com/unit/germ_flakpanzer_38t_gepard","src":[]},"flak_early:germ_sdkfz_6_2_flak36":{"mfr":"Büssing-NAG","mfrSource":"wiki","by":"Büssing-NAG (5-tonne half-track)","prod":"1939 – 1941","built":"203","text":"A 3.7 cm Flak 36 on the 5-tonne Sd.Kfz. 6 half-track, used to give motorised columns protection against low-flying aircraft.","wiki":"https://wiki.warthunder.com/unit/germ_sdkfz_6_2_flak36","src":[]},"artillery:germ_sturmpanzer_ii":{"mfr":"Alkett","mfrSource":"wiki","by":"Alkett","prod":"Dec 1941 – Jan 1942","built":"12","text":"A 15 cm sIG 33 infantry gun on a lengthened Panzer II chassis. All twelve went to North Africa with the 707th and 708th heavy infantry-gun companies of the 90th Light Division and were lost by the surrender in Tunisia in 1943.","wiki":"https://wiki.warthunder.com/unit/germ_sturmpanzer_ii","src":[]},"artillery:germ_hummel":{"mfr":"Deutsche Eisenwerke","mfrSource":"historical","by":"Deutsche Eisenwerke (design by Alkett)","prod":"1943 – 1945","built":"714 guns, 157 ammunition carriers","text":"The Hummel carried the 15 cm sFH 18 howitzer on the Geschützwagen III/IV chassis, giving panzer divisions mobile heavy artillery. It first fought at Kursk in 1943.","wiki":"https://wiki.warthunder.com/unit/germ_hummel","src":[]},"artillery:germ_sturmpanzer_iv_brummbar":{"mfr":"Alkett","mfrSource":"wiki","by":"Deutsche Eisenwerke","prod":"Apr 1943 – Mar 1945","built":"just over 300","text":"The Sturmpanzer IV put a 15 cm StuH 43 howitzer in a heavily armoured casemate on the Panzer IV chassis for close support against buildings and fortifications. Allied troops nicknamed it Brummbär (grizzly bear).","wiki":"https://wiki.warthunder.com/unit/germ_sturmpanzer_iv_brummbar","src":[]},"sdkfz_light:germ_sdkfz_221_s_pz_b_41":{"mfr":"Eisenwerk Weserhütte","mfrSource":"wiki","by":"Horch chassis; bodies and assembly by Schichau, MNH and others","prod":"1935 – 1940 (Sd.Kfz. 221)","built":"at least 339 Sd.Kfz. 221","text":"The Sd.Kfz. 221 light armoured car served reconnaissance units with a single machine gun. From 1942 some were rearmed with the 2.8 cm sPzB 41 squeeze-bore anti-tank gun to give scouts a way to deal with light armour.","wiki":"https://wiki.warthunder.com/unit/germ_sdkfz_221_s_pz_b_41","src":[["Wikipedia · Leichter Panzerspähwagen","https://en.wikipedia.org/wiki/Leichter_Panzersp%C3%A4hwagen"]]},"sdkfz_light:germ_sdkfz_222":{"mfr":"Eisenwerk Weserhütte","mfrSource":"wiki","by":"Horch chassis; bodies and assembly by Schichau, MNH and others","prod":"1937 – 1943","built":"at least 990","text":"The standard German light armoured car, with a 2 cm KwK 30/38 and machine gun in an open turret covered by a wire anti-grenade screen. It served throughout the war in reconnaissance battalions.","wiki":"https://wiki.warthunder.com/unit/germ_sdkfz_222","src":[["Wikipedia · Leichter Panzerspähwagen","https://en.wikipedia.org/wiki/Leichter_Panzersp%C3%A4hwagen"]]},"sdkfz_light:germ_pzkpfw_38t_aufklarungspanzer":{"mfr":"ČKD / BMM","mfrSource":"wiki","by":"BMM (ČKD)","prod":"Feb – Mar 1944","built":"70","text":"A reconnaissance vehicle on the late Panzer 38(t) chassis, using the open 2 cm turret of the Sd.Kfz. 222 armoured car.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_38t_aufklarungspanzer","src":[["Wikipedia · Leichter Panzerspähwagen","https://en.wikipedia.org/wiki/Leichter_Panzersp%C3%A4hwagen"]]},"sdkfz_light:germ_amd_35_kwk":{"mfr":"Panhard","mfrSource":"wiki","by":"Panhard (captured AMD 35 / Panhard 178)","prod":"German conversion 1944","built":"","text":"Germany took over French Panhard 178 armoured cars as Panzerspähwagen P204(f). In 1944 some were rebuilt with an open-topped turret and a 5 cm KwK 38 to give them anti-tank firepower.","wiki":"https://wiki.warthunder.com/unit/germ_amd_35_kwk","src":[["Wikipedia · Leichter Panzerspähwagen","https://en.wikipedia.org/wiki/Leichter_Panzersp%C3%A4hwagen"]]},"sdkfz_light:germ_amd_35_kwk39":{"mfr":"Panhard","mfrSource":"wiki","by":"Panhard (captured AMD 35 / Panhard 178)","prod":"German conversion 1944","built":"","text":"A further rearmament of the captured Panhard 178 with the long 5 cm KwK 39/1 L/60, the gun of the Puma armoured car, in an open turret.","wiki":"https://wiki.warthunder.com/unit/germ_amd_35_kwk39","src":[["Wikipedia · Leichter Panzerspähwagen","https://en.wikipedia.org/wiki/Leichter_Panzersp%C3%A4hwagen"]]},"czech:germ_pzkpfw_35t":{"mfr":"Škoda","mfrSource":"wiki","by":"Škoda (also ČKD)","prod":"taken over March 1939","built":"244 taken into German service","text":"The Škoda LT vz. 35 was taken over when Germany occupied Czechoslovakia in March 1939. As the Pz.Kpfw. 35(t) it fought in Poland, France and the opening months of the invasion of the Soviet Union, where cold weather exposed its pneumatic steering.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_35t","src":[["Wikipedia · Panzer 38(t)","https://en.wikipedia.org/wiki/Panzer_38(t)"]]},"czech:germ_pzkpfw_38t_ausf_a":{"mfr":"ČKD / BMM","mfrSource":"wiki","by":"ČKD (as BMM under occupation)","prod":"1939","built":"1,414 Panzer 38(t) for Germany in total","text":"ČKD's LT vz. 38 was so reliable that Germany kept it in production after the occupation. The first German order, the Ausf. A, armed with a 3.7 cm gun, fought in Poland and France.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_38t_ausf_a","src":[["Wikipedia · Panzer 38(t)","https://en.wikipedia.org/wiki/Panzer_38(t)"]]},"czech:germ_pzkpfw_38t_ausf_f":{"mfr":"ČKD / BMM","mfrSource":"wiki","by":"BMM (ČKD), Prague","prod":"1941 – 1942","built":"1,414 Panzer 38(t) for Germany in total","text":"The E and F raised frontal armour to 50 mm. By 1942 the 3.7 cm gun was obsolete, and the chassis went on to carry the Marder III, Grille and Hetzer.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_38t_ausf_f","src":[["Wikipedia · Panzer 38(t)","https://en.wikipedia.org/wiki/Panzer_38(t)"]]},"panzer3:germ_pzkpfw_iii_ausf_b":{"mfr":"Daimler-Benz","mfrSource":"wiki","by":"Daimler-Benz","prod":"1937","built":"10","text":"Daimler-Benz won the 1934 contract for the Panzer III, the panzer division's main battle tank. The B was a pre-series trial version with eight small road wheels on leaf springs; it was soon withdrawn.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_iii_ausf_b","src":[["Wikipedia · Panzer III","https://en.wikipedia.org/wiki/Panzer_III"]]},"panzer3:germ_pzkpfw_iii_ausf_e":{"mfr":"Daimler-Benz","mfrSource":"wiki","by":"Daimler-Benz","prod":"1938 – 1939","built":"96","text":"The E introduced the torsion-bar suspension with six road wheels and 30 mm armour that defined the Panzer III. It fought in Poland with the 3.7 cm gun.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_iii_ausf_e","src":[["Wikipedia · Panzer III","https://en.wikipedia.org/wiki/Panzer_III"]]},"panzer3:germ_pzkpfw_iii_ausf_f":{"mfr":"Daimler-Benz","mfrSource":"wiki","by":"Daimler-Benz, Alkett, Henschel, MAN, FAMO, MIAG","prod":"1939 – 1941","built":"about 450","text":"The F was the main Panzer III of the French campaign. Late vehicles and many refits received the 5 cm KwK 38 L/42 as the 3.7 cm gun proved too weak.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_iii_ausf_f","src":[["Wikipedia · Panzer III","https://en.wikipedia.org/wiki/Panzer_III"]]},"panzer3:germ_pzkpfw_iii_ausf_j_l42":{"mfr":"Daimler-Benz","mfrSource":"wiki","by":"Daimler-Benz, Alkett, Henschel, MAN, MIAG, MNH, Wegmann","prod":"1941 – 1942","built":"1,521 Ausf. J","text":"The J raised basic armour to 50 mm and carried the 5 cm KwK 38 L/42. It was the main German tank in North Africa and the Soviet Union in 1941–42.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_iii_ausf_j_l42","src":[["Wikipedia · Panzer III","https://en.wikipedia.org/wiki/Panzer_III"]]},"panzer3:germ_pzkpfw_iii_ausf_j":{"mfr":"Daimler-Benz","mfrSource":"wiki","by":"Daimler-Benz, Alkett, Henschel, MAN, MIAG, MNH, Wegmann","prod":"1941 – 1942","built":"","text":"Late J tanks, known as J1, got the long 5 cm KwK 39 L/60, which the British called the 'Mark III Special'. It restored some of the Panzer III's punch against the T-34 and Allied tanks.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_iii_ausf_j","src":[["Wikipedia · Panzer III","https://en.wikipedia.org/wiki/Panzer_III"]]},"panzer3:germ_pzkpfw_iii_ausf_l":{"mfr":"Daimler-Benz","mfrSource":"wiki","by":"Daimler-Benz, Alkett, Henschel, MAN, MIAG, MNH, Wegmann","prod":"1942","built":"1,470 (counting late J with the L/60)","text":"The L combined the L/60 gun with a 20 mm spaced plate in front of the mantlet and superstructure, the last effort to keep the Panzer III competitive as a battle tank.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_iii_ausf_l","src":[["Wikipedia · Panzer III","https://en.wikipedia.org/wiki/Panzer_III"]]},"panzer3:germ_pzkpfw_iii_ausf_m":{"mfr":"Daimler-Benz","mfrSource":"wiki","by":"MAN, MIAG, MNH, Wegmann, Henschel","prod":"1942 – 1943","built":"517","text":"The M added deep-fording equipment and Schürzen. Production was cut short as factories switched to the StuG III.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_iii_ausf_m","src":[["Wikipedia · Panzer III","https://en.wikipedia.org/wiki/Panzer_III"]]},"panzer3:germ_pzkpfw_iii_ausf_n":{"mfr":"Daimler-Benz","mfrSource":"wiki","by":"Converted and new-built on L and M chassis","prod":"1942 – 1943","built":"614","text":"The N carried the short 7.5 cm L/24 from the early Panzer IV for close support. Many served alongside Tiger Is in heavy tank battalions to cover them with high-explosive fire.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_iii_ausf_n","src":[["Wikipedia · Panzer III","https://en.wikipedia.org/wiki/Panzer_III"]]},"marder_ww2:germ_panzerjager_1":{"mfr":"Alkett","mfrSource":"wiki","by":"Alkett (some by Klöckner-Humboldt-Deutz)","prod":"Mar 1940 – Feb 1941","built":"202","text":"Germany's first self-propelled anti-tank gun put the Czech 4.7 cm PaK(t) behind a shield on the obsolete Panzer I Ausf. B. It fought in France, North Africa and Russia.","wiki":"https://wiki.warthunder.com/unit/germ_panzerjager_1","src":[["Wikipedia · Marder III","https://en.wikipedia.org/wiki/Marder_III"],["Wikipedia · Panzerjäger I","https://en.wikipedia.org/wiki/Panzerj%C3%A4ger_I"]]},"marder_ww2:germ_pzkpfw_38t_marder_iii":{"mfr":"ČKD / BMM","mfrSource":"wiki","by":"BMM (ČKD), Prague","prod":"Apr – Nov 1942","built":"344","text":"Captured Soviet 76.2 mm F-22 guns, rechambered as the PaK 36(r), were mounted on the Panzer 38(t) to give infantry a mobile answer to the T-34.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_38t_marder_iii","src":[["Wikipedia · Marder III","https://en.wikipedia.org/wiki/Marder_III"],["Wikipedia · Panzerjäger I","https://en.wikipedia.org/wiki/Panzerj%C3%A4ger_I"]]},"marder_ww2:germ_pzkpfw_38t_marder_iii_ausf_h":{"mfr":"ČKD / BMM","mfrSource":"wiki","by":"BMM (ČKD), Prague","prod":"Nov 1942 – Apr 1943","built":"275 new, 175 converted","text":"The Ausf. H mounted the German 7.5 cm PaK 40 in a fighting compartment over the centre of the Panzer 38(t) hull.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_38t_marder_iii_ausf_h","src":[["Wikipedia · Marder III","https://en.wikipedia.org/wiki/Marder_III"],["Wikipedia · Panzerjäger I","https://en.wikipedia.org/wiki/Panzerj%C3%A4ger_I"]]},"halftracks:germ_sdkfz_251_21":{"mfr":"Hanomag","mfrSource":"wiki","by":"Hanomag-designed Sd.Kfz. 251","prod":"1944 – 1945","built":"","text":"The 'Drilling' mounted three MG 151 aircraft cannons on the standard armoured personnel carrier to protect columns from low-flying aircraft; the guns also proved deadly against infantry.","wiki":"https://wiki.warthunder.com/unit/germ_sdkfz_251_21","src":[]},"panzer2:germ_pzkpfw_ii_ausf_c":{"mfr":"MAN","mfrSource":"wiki","by":"MAN, Daimler-Benz, Alkett, FAMO, Henschel, MIAG, Wegmann","prod":"Jun 1938 – Apr 1940","built":"1,113 Ausf. a–C","text":"Ordered as a stop-gap until the Panzer III and IV arrived, the Panzer II with its 2 cm gun made up much of the panzer force in Poland and France. The C was the standard early version.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_ii_ausf_c","src":[["Wikipedia · Panzer II","https://en.wikipedia.org/wiki/Panzer_II"]]},"panzer2:germ_pzkpfw_ii_ausf_f":{"mfr":"MAN","mfrSource":"wiki","by":"FAMO and others","prod":"Mar 1941 – Jul 1942","built":"509","text":"The F had 35 mm armour on a flat front plate. By then the Panzer II had become a reconnaissance tank, and its chassis was reused for the Marder II and Wespe.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_ii_ausf_f","src":[["Wikipedia · Panzer II","https://en.wikipedia.org/wiki/Panzer_II"]]},"panzer2:germ_pzkpfw_ii_ausf_c_dak":{"mfr":"MAN","mfrSource":"wiki","by":"MAN, Daimler-Benz, Alkett, FAMO, Henschel, MIAG, Wegmann","prod":"1938 – 1940","built":"","text":"A Panzer II C as used by the Deutsches Afrikakorps in North Africa from 1941, with desert camouflage and stowage.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_ii_ausf_c_dak","src":[["Wikipedia · Panzer II","https://en.wikipedia.org/wiki/Panzer_II"]]},"stug:germ_stug_iii_ausf_a":{"mfr":"Daimler-Benz","mfrSource":"wiki","by":"Daimler-Benz","prod":"Jan – May 1940","built":"30 + 6","text":"The Sturmgeschütz gave infantry armoured, low-profile fire support with a short 7.5 cm gun in a fixed casemate on the Panzer III chassis. The first battery fought in France in 1940.","wiki":"https://wiki.warthunder.com/unit/germ_stug_iii_ausf_a","src":[["Wikipedia · Sturmgeschütz III","https://en.wikipedia.org/wiki/Sturmgesch%C3%BCtz_III"]]},"stug:germ_stuh_iii_ausf_g":{"mfr":"Alkett","mfrSource":"wiki","by":"Alkett","prod":"Mar 1943 – 1945","built":"1,299","text":"Once the StuG became a tank killer, the StuH 42 brought back the support role with a 10.5 cm howitzer on the Ausf. G chassis.","wiki":"https://wiki.warthunder.com/unit/germ_stuh_iii_ausf_g","src":[["Wikipedia · Sturmgeschütz III","https://en.wikipedia.org/wiki/Sturmgesch%C3%BCtz_III"]]},"stug:germ_stug_iii_ausf_f":{"mfr":"Daimler-Benz","mfrSource":"wiki","by":"Alkett","prod":"Mar – Sep 1942","built":"366","text":"The F was the first StuG with the long 7.5 cm StuK 40 L/43, turning the assault gun into one of Germany's most effective anti-tank vehicles.","wiki":"https://wiki.warthunder.com/unit/germ_stug_iii_ausf_f","src":[["Wikipedia · Sturmgeschütz III","https://en.wikipedia.org/wiki/Sturmgesch%C3%BCtz_III"]]},"stug:germ_stug_iii_ausf_g":{"mfr":"Alkett / MIAG","mfrSource":"wiki","by":"Alkett and MIAG","prod":"Dec 1942 – Apr 1945","built":"about 8,400","text":"The G was the most numerous German armoured fighting vehicle of the war, with the L/48 gun, a cupola and, later, a cast 'Saukopf' mantlet. Alkett and MIAG together built about 10,000 StuG IIIs.","wiki":"https://wiki.warthunder.com/unit/germ_stug_iii_ausf_g","src":[["Wikipedia · Sturmgeschütz III","https://en.wikipedia.org/wiki/Sturmgesch%C3%BCtz_III"]]},"proto_early:germ_pzkpfw_38t_na":{"mfr":"ČKD / BMM","mfrSource":"wiki","by":"BMM (ČKD)","prod":"1942","built":"prototypes","text":"The 'new model' was a faster, better-armoured reconnaissance tank derived from the 38(t). It competed with the Panzer II Ausf. L Luchs and was not ordered.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_38t_na","src":[]},"proto_early:germ_nbfz_vi":{"mfr":"Rheinmetall / Rheinmetall-Borsig","mfrSource":"wiki","by":"Rheinmetall (Krupp designed an alternative turret)","prod":"1934 – 1936","built":"5 (2 mild steel, 3 armoured)","text":"The Neubaufahrzeug was an inter-war multi-turreted heavy tank with 7.5 cm and 3.7 cm guns. Three armoured examples were sent to Norway in 1940, where one fought near Lillehammer.","wiki":"https://wiki.warthunder.com/unit/germ_nbfz_vi","src":[]},"sdkfz234:germ_sdkfz_234_1":{"mfr":"Büssing-NAG","mfrSource":"wiki","by":"Büssing-NAG (chassis); turrets by Daimler-Benz and Schichau","prod":"mid-1944 – early 1945","built":"about 200","text":"The Sd.Kfz. 234 eight-wheeler had a Tatra air-cooled diesel suited to hot climates and could be driven in either direction. The 234/1 carried a 2 cm gun in an open turret.","wiki":"https://wiki.warthunder.com/unit/germ_sdkfz_234_1","src":[["Wikipedia · Sd.Kfz. 234","https://en.wikipedia.org/wiki/Sd.Kfz._234"]]},"sdkfz234:germ_sdkfz_234_3":{"mfr":"Büssing-NAG","mfrSource":"wiki","by":"Büssing-NAG","prod":"Jun – Dec 1944","built":"88","text":"The 234/3 mounted the short 7.5 cm K51 L/24 in an open superstructure for close support of reconnaissance units.","wiki":"https://wiki.warthunder.com/unit/germ_sdkfz_234_3","src":[["Wikipedia · Sd.Kfz. 234","https://en.wikipedia.org/wiki/Sd.Kfz._234"]]},"sdkfz234:germ_sdkfz_234_2":{"mfr":"Büssing-NAG","mfrSource":"wiki","by":"Büssing-NAG; turret by Daimler-Benz","prod":"Sep 1943 – Sep 1944","built":"101","text":"The Puma carried a 5 cm KwK 39/1 L/60 in an enclosed turret originally designed for the VK 16.02 Leopard light tank.","wiki":"https://wiki.warthunder.com/unit/germ_sdkfz_234_2","src":[["Wikipedia · Sd.Kfz. 234","https://en.wikipedia.org/wiki/Sd.Kfz._234"]]},"sdkfz234:germ_sdkfz_234_4":{"mfr":"Büssing-NAG","mfrSource":"wiki","by":"Büssing-NAG","prod":"Dec 1944 – Mar 1945","built":"89","text":"Built at Hitler's insistence, the 234/4 put a 7.5 cm PaK 40 anti-tank gun, minus its wheels, on the eight-wheeled chassis.","wiki":"https://wiki.warthunder.com/unit/germ_sdkfz_234_4","src":[["Wikipedia · Sd.Kfz. 234","https://en.wikipedia.org/wiki/Sd.Kfz._234"]]},"proto_ww2_td:germ_pzsfl_iva_dickermax":{"mfr":"Krupp","mfrSource":"wiki","by":"Krupp","prod":"1941","built":"2","text":"A 10.5 cm K18 gun on a modified Panzer IV chassis, built to attack bunkers and heavy tanks. Both were tested in combat on the Eastern Front in 1941.","wiki":"https://wiki.warthunder.com/unit/germ_pzsfl_iva_dickermax","src":[]},"proto_ww2_td:germ_pzsflk40_sturer_emil":{"mfr":"Rheinmetall / Rheinmetall-Borsig","mfrSource":"wiki","by":"Henschel chassis, Rheinmetall gun","prod":"1941 – 1942","built":"2","text":"A 12.8 cm K40 on a lengthened VK 30.01 (H) chassis. Both vehicles served with 521st Panzerjäger Battalion; one was captured at Stalingrad and is in the Kubinka museum.","wiki":"https://wiki.warthunder.com/unit/germ_pzsflk40_sturer_emil","src":[]},"proto_ww2_td:germ_pzkpfw_ii_ausf_h":{"mfr":"MAN","mfrSource":"wiki","by":"MAN","prod":"1941 – 1942","built":"2","text":"Two light self-propelled guns with a 5 cm PaK 38 were built on a new Panzer II-derived chassis; both were sent to the Eastern Front.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_ii_ausf_h","src":[]},"proto_ww2_td:germ_waffentrager_krupp_steyr":{"mfr":"Krupp","mfrSource":"wiki","by":"Krupp and Steyr","prod":"1944 – 1945","built":"prototype stage","text":"The Waffenträger programme sought a cheap, light carrier for the 8.8 cm PaK 43 with all-round traverse. Krupp–Steyr's design was being prepared for production when the war ended.","wiki":"https://wiki.warthunder.com/unit/germ_waffentrager_krupp_steyr","src":[]},"flak_heavy:germ_sdkfz_9_flak37":{"mfr":"FAMO","mfrSource":"historical","by":"FAMO (18-tonne Sd.Kfz. 9 half-track)","prod":"1940 conversions","built":"few","text":"FAMO's 18-tonne Sd.Kfz. 9 was Germany's largest half-track. A small number were fitted with an 8.8 cm Flak on a platform for use against both aircraft and tanks.","wiki":"https://wiki.warthunder.com/unit/germ_sdkfz_9_flak37","src":[]},"proto_ww2_tanks:germ_vk_3002m":{"mfr":"MAN","mfrSource":"wiki","by":"MAN","prod":"1942","built":"2 prototypes","text":"MAN's proposal won the competition against Daimler-Benz's T-34-like VK 30.02 (DB) and became the Panther. The prototypes still differed in many details from the production tank.","wiki":"https://wiki.warthunder.com/unit/germ_vk_3002m","src":[]},"proto_ww2_tanks:germ_pzkpfw_vi_tiger_p":{"mfr":"Porsche","mfrSource":"wiki","by":"Porsche (assembled at the Nibelungenwerk)","prod":"1942","built":"10 tanks (100 chassis)","text":"Porsche's heavy tank used petrol-electric drive and was ordered before trials. It lost to Henschel's design; ten were completed as tanks and most of the 100 chassis became Ferdinands.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_vi_tiger_p","src":[]},"proto_ww2_tanks:germ_panzerbefelhswagen_vi_p":{"mfr":"Porsche","mfrSource":"wiki","by":"Porsche","prod":"1944","built":"1","text":"One VK 45.01 (P) was rebuilt with extra frontal armour as a command tank for the 653rd Heavy Panzerjäger Battalion and used on the Eastern Front in 1944.","wiki":"https://wiki.warthunder.com/unit/germ_panzerbefelhswagen_vi_p","src":[]},"proto_ww2_tanks:germ_pzkpfw_vi_ausf_b_tiger_iih_sla":{"mfr":"Henschel","mfrSource":"wiki","by":"Henschel; Sla.16 diesel by Simmering-Graz-Pauker","prod":"1944 – 1945 (engine development)","built":"not fielded","text":"Simmering-Graz-Pauker developed the X-16 Sla.16 diesel to give the Tiger II more power and range. The engine did not reach production before the war ended.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_vi_ausf_b_tiger_iih_sla","src":[]},"proto_ww2_tanks:germ_panther_ii":{"mfr":"MAN","mfrSource":"wiki","by":"MAN (design)","prod":"1943 – 1945","built":"1 hull","text":"The Panther II would have had thicker armour and Tiger II components. Only one hull was completed; it now carries a Panther G turret at the US Army's armour museum.","wiki":"https://wiki.warthunder.com/unit/germ_panther_ii","src":[]},"proto_ww2_tanks:germ_pzkpfw_vi_ausf_b_tiger_iih_kwk46":{"mfr":"Henschel","mfrSource":"wiki","by":"Krupp (gun study)","prod":"1944","built":"not built","text":"Krupp studied fitting the Tiger II with a 10.5 cm KwK 46 L/68. It was never built; War Thunder shows how it might have looked.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_vi_ausf_b_tiger_iih_kwk46","src":[]},"proto_ww2_tanks:germ_pzkpfw_e_100":{"mfr":"Henschel","mfrSource":"wiki","by":"Adlerwerke (design); assembly at Henschel's Haustenbeck site","prod":"1944 – 1945","built":"1 incomplete chassis","text":"The E-100 was the heaviest of the Entwicklung series. Only its chassis was finished; it was taken to Britain for study and scrapped.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_e_100","src":[]},"proto_ww2_tanks:germ_pzkpfw_maus":{"mfr":"Porsche","mfrSource":"wiki","by":"Porsche (design), Krupp (hull and turret), Alkett (assembly)","prod":"1943 – 1944","built":"2","text":"At about 188 tonnes, the Maus was the heaviest tank ever completed. The Soviets captured both prototypes; one hull with the other's turret is in the Kubinka museum.","wiki":"https://wiki.warthunder.com/unit/germ_pzkpfw_maus","src":[]},"flak_panzer4:germ_flakpanzer_iv_ostwind":{"mfr":"Deutsche Eisenwerke","mfrSource":"wiki","by":"Deutsche Eisenwerke, Teplitz-Schönau","prod":"1944 – 1945","built":"about 40","text":"The Ostwind put a 3.7 cm Flak 43 in an open six-sided turret on a rebuilt Panzer IV chassis, with more range and hitting power than the Wirbelwind's 2 cm guns.","wiki":"https://wiki.warthunder.com/unit/germ_flakpanzer_iv_ostwind","src":[]},"flak_panzer4:germ_flakpanzer_iv_wirbelwind":{"mfr":"Ostbau Sagan","mfrSource":"historical","by":"Ostbau Sagan (conversions)","prod":"1944","built":"about 100","text":"Ostbau in Sagan converted repaired Panzer IV hulls with an open nine-sided turret holding the 2 cm Flakvierling 38. It defended panzer regiments against fighter-bombers in 1944–45.","wiki":"https://wiki.warthunder.com/unit/germ_flakpanzer_iv_wirbelwind","src":[]},"nashorn:germ_panzerjager_nashorn":{"mfr":"Alkett","mfrSource":"wiki","by":"Alkett (design), Deutsche Eisenwerke, Teplitz-Schönau","prod":"1943 – 1945","built":"494","text":"The Nashorn (first called Hornisse) carried the 8.8 cm PaK 43/1 on the Geschützwagen III/IV chassis. It could kill tanks at long range but had only light, open armour.","wiki":"https://wiki.warthunder.com/unit/germ_panzerjager_nashorn","src":[["Wikipedia · Nashorn","https://en.wikipedia.org/wiki/Nashorn"]]},"proto_ww2_aa:germ_flakpanzer_iv_ostwind_2":{"mfr":"Deutsche Eisenwerke","mfrSource":"wiki","by":"Deutsche Eisenwerke","prod":"1944 – 1945","built":"1 prototype","text":"Ostwind II would have mounted the twin 3.7 cm Flakzwilling 44 in an enlarged open turret. A prototype was built but production never began.","wiki":"https://wiki.warthunder.com/unit/germ_flakpanzer_iv_ostwind_2","src":[]},"proto_ww2_aa:germ_vsw_flak_41":{"mfr":"Krupp","mfrSource":"wiki","by":"Krupp","prod":"1944","built":"prototypes","text":"The Versuchsflakwagen carried an 8.8 cm Flak 41 on a lengthened chassis with Panzer IV parts. Its sides folded down to form a firing platform.","wiki":"https://wiki.warthunder.com/unit/germ_vsw_flak_41","src":[]},"proto_ww2_aa:germ_flakpanzer_iv_ostwind_2_net":{"mfr":"Deutsche Eisenwerke","mfrSource":"wiki","by":"Deutsche Eisenwerke","prod":"1944 – 1945","built":"1 prototype","text":"War Thunder's camouflaged event version of the experimental twin-3.7 cm Ostwind II.","wiki":"https://wiki.warthunder.com/unit/germ_flakpanzer_iv_ostwind_2_net","src":[]},"proto_ww2_aa:germ_flakpanzer_zerstorer_45":{"mfr":"Deutsche Eisenwerke","mfrSource":"wiki","by":"Deutsche Eisenwerke","prod":"1945","built":"a few","text":"A late-war attempt to raise firepower with four 3 cm MK 103 cannons on a Panzer IV chassis, in an open mount.","wiki":"https://wiki.warthunder.com/unit/germ_flakpanzer_zerstorer_45","src":[]},"proto_ww2_aa:germ_flakpanzer_iv_kugelblitz":{"mfr":"Daimler-Benz","mfrSource":"wiki","by":"Daimler-Benz (turret)","prod":"Feb 1945","built":"probably two to five","text":"The first enclosed German anti-aircraft turret: a ball with two 3 cm MK 103 cannons on a Panzer IV chassis. Only a handful were completed at the end of the war.","wiki":"https://wiki.warthunder.com/unit/germ_flakpanzer_iv_kugelblitz","src":[]},"proto_ww2_aa:germ_flakpanzer_v_coelian":{"mfr":"Rheinmetall / Rheinmetall-Borsig","mfrSource":"wiki","by":"Rheinmetall-Borsig (design)","prod":"1943 – 1944","built":"wooden mock-up","text":"The Coelian project planned an enclosed twin 3.7 cm anti-aircraft turret on the Panther hull. It never went beyond a wooden mock-up.","wiki":"https://wiki.warthunder.com/unit/germ_flakpanzer_v_coelian","src":[]},"jagdpanzer:germ_jgdpz_iv_l48":{"mfr":"Vomag","mfrSource":"historical","by":"Vomag, Plauen","prod":"Jan – Nov 1944","built":"769–784","text":"Vomag's low, well-sloped tank destroyer on the Panzer IV chassis carried the same 7.5 cm L/48 gun as the StuG and Panzer IV.","wiki":"https://wiki.warthunder.com/unit/germ_jgdpz_iv_l48","src":[["Wikipedia · Jagdpanzer IV","https://en.wikipedia.org/wiki/Jagdpanzer_IV"]]},"jagdpanzer:germ_jgdpz_38t":{"mfr":"ČKD / BMM","mfrSource":"wiki","by":"BMM and Škoda","prod":"Apr 1944 – May 1945","built":"about 2,584","text":"Small, cheap and hard to spot, the Jagdpanzer 38 (Hetzer) used the 38(t) running gear with the 7.5 cm PaK 39. Switzerland and Czechoslovakia used it after the war.","wiki":"https://wiki.warthunder.com/unit/germ_jgdpz_38t","src":[["Wikipedia · Jagdpanzer IV","https://en.wikipedia.org/wiki/Jagdpanzer_IV"]]},"jagdpanzer:iv70v":{"mfr":"Vomag","mfrSource":"historical","by":"Vomag, Plauen","prod":"Aug 1944 – Apr 1945","built":"930–940","text":"The Jagdpanzer IV re-armed with the 7.5 cm L/70, the Panther's gun. The heavy gun made it nose-heavy and hard on the front road wheels.","wiki":"https://wiki.warthunder.com/unit/germ_pz_iv_l70","src":[["Wikipedia · Jagdpanzer IV","https://en.wikipedia.org/wiki/Jagdpanzer_IV"]]},"jagdpanzer:germ_pz_iv_l70_a":{"mfr":"Alkett","mfrSource":"wiki","by":"Nibelungenwerk; superstructure design by Alkett","prod":"Aug 1944 – Mar 1945","built":"278","text":"An interim tank destroyer: a tall casemate with the 7.5 cm L/70 on an otherwise standard Panzer IV hull.","wiki":"https://wiki.warthunder.com/unit/germ_pz_iv_l70_a","src":[["Wikipedia · Jagdpanzer IV","https://en.wikipedia.org/wiki/Jagdpanzer_IV"]]},"kanonen:germ_kanonenjagdpanzer":{"mfr":"Rheinstahl","mfrSource":"wiki","by":"Henschel and Hanomag","prod":"1966 – 1967","built":"770 (plus 80 for Belgium)","text":"West Germany's gun tank destroyer revived the wartime Jagdpanzer idea with a 90 mm gun in a low casemate. It was converted to the Jaguar 2 when missiles took over the role.","wiki":"https://wiki.warthunder.com/unit/germ_kanonenjagdpanzer","src":[["Wikipedia · Kanonenjagdpanzer","https://en.wikipedia.org/wiki/Kanonenjagdpanzer"]]},"ferdinand:germ_panzerjager_tiger_p_ferdinand":{"mfr":"Porsche","mfrSource":"wiki","by":"Nibelungenwerk (conversion), design by Porsche","prod":"Mar – May 1943","built":"91","text":"The unused Porsche Tiger chassis were turned into heavy tank destroyers with the 8.8 cm PaK 43/2 and 200 mm frontal armour. Eighty-nine fought at Kursk.","wiki":"https://wiki.warthunder.com/unit/germ_panzerjager_tiger_p_ferdinand","src":[["Wikipedia · Elefant","https://en.wikipedia.org/wiki/Elefant"]]},"ferdinand:germ_panzerjager_tiger_p_elefant":{"mfr":"Porsche","mfrSource":"wiki","by":"Nibelungenwerk (rebuild)","prod":"Jan – Apr 1944","built":"48 rebuilt","text":"Surviving Ferdinands were rebuilt with a hull machine gun, a new commander's cupola and Zimmerit, and renamed Elefant. They fought in Italy and on the Eastern Front.","wiki":"https://wiki.warthunder.com/unit/germ_panzerjager_tiger_p_elefant","src":[["Wikipedia · Elefant","https://en.wikipedia.org/wiki/Elefant"]]},"hs30:germ_spz_12_3":{"mfr":"Hispano-Suiza","mfrSource":"wiki","by":"Hispano-Suiza (design); built by Leyland, Henschel and Hanomag","prod":"1958 – 1962","built":"2,176","text":"The Bundeswehr's first infantry carrier, with a 20 mm cannon. The LGS variant added a 106 mm M40 recoilless rifle on the roof from 1965.","wiki":"https://wiki.warthunder.com/unit/germ_spz_12_3","src":[["Wikipedia · HS.30","https://en.wikipedia.org/wiki/HS.30"]]},"proto_cold_light:germ_ru251":{"mfr":"Hanomag","mfrSource":"wiki","by":"Hanomag","prod":"1960s","built":"prototypes","text":"A light reconnaissance tank with a 90 mm gun based on Kanonenjagdpanzer components, intended to replace the US M41. The Bundeswehr chose not to order it.","wiki":"https://wiki.warthunder.com/unit/germ_ru251","src":[]},"proto_cold_light:germ_marder_df_105":{"mfr":"Thyssen-Henschel","mfrSource":"wiki","by":"Thyssen-Henschel (Franco-German project)","prod":"1980s","built":"prototype","text":"An export-only fire-support vehicle that married the Marder hull to the oscillating turret and 105 mm gun of the Austrian SK-105 Kürassier. No foreign customer ordered it, and it remained a prototype.","wiki":"https://wiki.warthunder.com/unit/germ_marder_df_105","src":[]},"proto_cold_light:germ_spz_oerlikon_raketenautomat":{"mfr":"Oerlikon","mfrSource":"wiki","by":"Oerlikon","prod":"1964","built":"1 prototype","text":"An HS.30 chassis with twin Oerlikon rocket launchers. The army chose another rocket-artillery system.","wiki":"https://wiki.warthunder.com/unit/germ_spz_oerlikon_raketenautomat","src":[]},"proto_cold_light:germ_marder_clovis":{"mfr":"Thyssen-Henschel","mfrSource":"wiki","by":"Thyssen-Henschel with GIAT (FL-20 turret)","prod":"mid-1980s","built":"prototype","text":"A follow-on to the DF105 using the new French FL-20 turret of 1984, with a 105 mm gun and a 20 mm coaxial cannon. The cheaper SK-105 and an ageing Marder hull left it without buyers.","wiki":"https://wiki.warthunder.com/unit/germ_marder_clovis","src":[]},"proto_cold_light:germ_begleitpanzer_57":{"mfr":"Thyssen-Henschel","mfrSource":"wiki","by":"Thyssen-Henschel and Bofors","prod":"late 1970s","built":"prototype","text":"A private-venture escort vehicle on the Marder chassis with a Bofors 57 mm automatic cannon and a TOW launcher, meant to protect mechanised infantry against vehicles and helicopters. The Bundeswehr did not adopt it.","wiki":"https://wiki.warthunder.com/unit/germ_begleitpanzer_57","src":[]},"proto_cold_light:germ_th_800_bismark":{"mfr":"Thyssen-Henschel","mfrSource":"wiki","by":"Henschel Wehrtechnik","prod":"early 1980s","built":"1 prototype","text":"The 41-tonne TH 800 was Henschel's entry, as the Class 3 prototype, in a South African competition for a wheeled combat vehicle. The lighter Rooikat won; the prototype ended up at the Bloemfontein war museum.","wiki":"https://wiki.warthunder.com/unit/germ_th_800_bismark","src":[]},"proto_cold_light:germ_th_400":{"mfr":"Thyssen-Henschel","mfrSource":"wiki","by":"Henschel Wehrtechnik (renamed R400 under Rheinmetall)","prod":"1980s; 105 mm turret tested 1996","built":"demonstrator","text":"A six-wheeled private venture that received a 105 mm gun turret in the 1990s. After Rheinmetall bought Henschel it was marketed as the R400, but no customer came forward; it is now a museum exhibit in the Netherlands.","wiki":"https://wiki.warthunder.com/unit/germ_th_400","src":[]},"proto_cold_light:germ_radpanzer_90":{"mfr":"Daimler-Benz","mfrSource":"wiki","by":"Daimler-Benz","prod":"1983 – 1986","built":"1 prototype","text":"Built for the Federal Ministry of Defence, this eight-wheeled vehicle mounted a 105 mm L7A3 gun. Budget cuts stopped it at the prototype stage, but its trials fed into the studies that led to the Boxer.","wiki":"https://wiki.warthunder.com/unit/germ_radpanzer_90","src":[]},"wiesel:germ_wiesel_1_mk20":{"mfr":"Rheinmetall / Rheinmetall-Borsig","mfrSource":"wiki","by":"Porsche (design); built by Rheinmetall (Industriewerke Saar)","prod":"ordered 1985; deliveries late 1980s – 1993","built":"133","text":"Porsche designed the Wiesel in the 1970s as a light, helicopter-portable weapon carrier for German airborne troops. The MK20 version carries a 20 mm Rh 202 cannon in a small one-man turret for reconnaissance and fire support.","wiki":"https://wiki.warthunder.com/unit/germ_wiesel_1_mk20","src":[["Wikipedia · Wiesel AWC","https://en.wikipedia.org/wiki/Wiesel_AWC"]]},"wiesel:germ_wiesel_1_tow":{"mfr":"Rheinmetall / Rheinmetall-Borsig","mfrSource":"wiki","by":"Porsche (design); built by Rheinmetall (Industriewerke Saar)","prod":"ordered 1985; deliveries late 1980s – 1993","built":"210","text":"The TOW version gave paratroopers a light, air-portable anti-tank missile carrier. Wiesels later served in Afghanistan, where their small size suited mountain roads.","wiki":"https://wiki.warthunder.com/unit/germ_wiesel_1_tow","src":[["Wikipedia · Wiesel AWC","https://en.wikipedia.org/wiki/Wiesel_AWC"]]},"modern_artillery:germ_pzh_2000":{"mfr":"Krauss-Maffei","mfrSource":"wiki","by":"Krauss-Maffei Wegmann (now KNDS Deutschland); gun by Rheinmetall","prod":"in service from 1998","built":"225 ordered for Germany, about 425 in total","text":"The PzH 2000 combines a 155 mm L/52 gun with an automatic loader that can fire several rounds in quick succession and land them at the same moment. It has fought in Afghanistan and, in large numbers, in Ukraine.","wiki":"https://wiki.warthunder.com/unit/germ_pzh_2000","src":[["Wikipedia · Panzerhaubitze 2000","https://en.wikipedia.org/wiki/Panzerhaubitze_2000"]]},"luchs:germ_sppz2_luchs_a2":{"mfr":"Daimler-Benz","mfrSource":"wiki","by":"Daimler-Benz (design); built by Rheinstahl / Thyssen-Henschel","prod":"1975 – 1977","built":"408","text":"An amphibious eight-wheeled reconnaissance vehicle with a second driver at the rear, so it can drive as fast backwards as forwards. The A2 modernisation brought new radios; the Luchs served until 2009 and was replaced by the Fennek.","wiki":"https://wiki.warthunder.com/unit/germ_sppz2_luchs_a2","src":[["Wikipedia · Spähpanzer Luchs","https://en.wikipedia.org/wiki/Sp%C3%A4hpanzer_Luchs"]]},"proto_cold_mbt:germ_erprobungstrager_3_achs_turm":{"mfr":"Rheinmetall / Rheinmetall-Borsig","mfrSource":"wiki","by":"Rheinmetall","prod":"1966","built":"1","text":"A Leopard-based test bed for a turret stabilised in all three axes to improve firing on the move. It did well in Bundeswehr trials but was judged too complex and costly; the prototype is in the Wehrtechnische Studiensammlung at Koblenz.","wiki":"https://wiki.warthunder.com/unit/germ_erprobungstrager_3_achs_turm","src":[["Wikipedia · Leopard 2","https://en.wikipedia.org/wiki/Leopard_2"]]},"proto_cold_mbt:germ_kpz_70":{"mfr":"Krauss-Maffei","mfrSource":"wiki","by":"Deutsche Entwicklungsgesellschaft (German side of the MBT-70 programme)","prod":"1963 – 1970","built":"7 German prototypes","text":"The US–West German MBT-70 promised hydropneumatic suspension, an automatic loader and a 152 mm gun/launcher. Germany withdrew in 1970 over cost, complexity and weight; its experience flowed into the Leopard 2.","wiki":"https://wiki.warthunder.com/unit/germ_kpz_70","src":[["Wikipedia · Leopard 2","https://en.wikipedia.org/wiki/Leopard_2"]]},"proto_cold_mbt:germ_vt_1_2":{"mfr":"MaK","mfrSource":"historical","by":"Maschinenbau Kiel (MaK)","prod":"1975","built":"1 (after the VT 1-1 of 1974)","text":"A turretless test tank with two fixed 120 mm guns, aimed by turning and tilting the whole vehicle. Trials showed the concept could work but brought no real advantage over the Leopard 2.","wiki":"https://wiki.warthunder.com/unit/germ_vt_1_2","src":[["Wikipedia · Leopard 2","https://en.wikipedia.org/wiki/Leopard_2"]]},"proto_cold_mbt:germ_leopard_a1a1_120":{"mfr":"Krauss-Maffei","mfrSource":"wiki","by":"Rheinmetall (private venture)","prod":"early 1980s; EMES 18 fire control added 1985","built":"several conversions","text":"Rheinmetall rearmed Leopard A1A1 tanks with the 120 mm smoothbore to win Bundeswehr or export orders, and later added the Leopard 1A5's fire control. The cost was high for the gain, and no one bought it.","wiki":"https://wiki.warthunder.com/unit/germ_leopard_a1a1_120","src":[["Wikipedia · Leopard 2","https://en.wikipedia.org/wiki/Leopard_2"]]},"proto_cold_mbt:germ_leopard_2k":{"mfr":"Krauss-Maffei","mfrSource":"wiki","by":"Krauss-Maffei","prod":"1972 – 1974","built":"16 hulls, 17 turrets","text":"The Leopard 2 prototype series (PT 1 to PT 17) tried 105 mm and 120 mm guns, different fire controls and, on some turrets, a 20 mm cannon on the roof, before the production design was fixed.","wiki":"https://wiki.warthunder.com/unit/germ_leopard_2k","src":[["Wikipedia · Leopard 2","https://en.wikipedia.org/wiki/Leopard_2"]]},"proto_cold_mbt:germ_leopard_2av":{"mfr":"Krauss-Maffei","mfrSource":"wiki","by":"Krauss-Maffei","prod":"1976","built":"3","text":"The 'Austere Version' was built to US requirements, with simpler fire control and spaced armour, and was evaluated in the US in 1976. The US Army chose the XM1, which became the Abrams.","wiki":"https://wiki.warthunder.com/unit/germ_leopard_2av","src":[["Wikipedia · Leopard 2","https://en.wikipedia.org/wiki/Leopard_2"]]},"proto_cold_mbt:germ_leopard_2_pt14":{"mfr":"Krauss-Maffei","mfrSource":"wiki","by":"Krauss-Maffei","prod":"c. 1980 – 1985","built":"test bed","text":"Krauss-Maffei fitted a nine-round bustle autoloader for the 120 mm gun to a modified turret, cutting the crew to three. The mechanism was unreliable and the army preferred a four-man crew, so it was dropped.","wiki":"https://wiki.warthunder.com/unit/germ_leopard_2_pt14","src":[["Wikipedia · Leopard 2","https://en.wikipedia.org/wiki/Leopard_2"]]},"tam:germ_thyssen_henschel_tam":{"mfr":"Thyssen-Henschel","mfrSource":"wiki","by":"Thyssen-Henschel (design); built in Argentina by TAMSE","prod":"1979 – 1983, 1994 – 1995","built":"about 200 tanks","text":"Thyssen-Henschel designed the Tanque Argentino Mediano from the Marder chassis for Argentina, with a 105 mm gun in a rear-mounted turret. Production was transferred to the state firm TAMSE.","wiki":"https://wiki.warthunder.com/unit/germ_thyssen_henschel_tam","src":[["Wikipedia · TAM (tank)","https://en.wikipedia.org/wiki/TAM_(tank)"]]},"tam:germ_thyssen_henschel_tam_2ip":{"mfr":"Thyssen-Henschel","mfrSource":"wiki","by":"Elbit Systems (upgrade prototype)","prod":"2016","built":"prototype","text":"Elbit's 2IP prototype added passive composite armour, based on IMI's Iron Wall, to the turret front and sides and the hull front. It did not have the 2C's new sights.","wiki":"https://wiki.warthunder.com/unit/germ_thyssen_henschel_tam_2ip","src":[["Wikipedia · TAM (tank)","https://en.wikipedia.org/wiki/TAM_(tank)"]]},"tam:germ_thyssen_henschel_tam_2c":{"mfr":"Thyssen-Henschel","mfrSource":"wiki","by":"Elbit Systems with the Argentine Army","prod":"first delivered 2013","built":"","text":"The 2C programme brought thermal sights for gunner and commander, a thermal sleeve, an auxiliary power unit, new ammunition and the ability to fire LAHAT missiles through the gun.","wiki":"https://wiki.warthunder.com/unit/germ_thyssen_henschel_tam_2c","src":[["Wikipedia · TAM (tank)","https://en.wikipedia.org/wiki/TAM_(tank)"]]},"modern_aa:germ_wiesel_2_adwc":{"mfr":"Rheinmetall / Rheinmetall-Borsig","mfrSource":"wiki","by":"Rheinmetall","prod":"in service from 2001","built":"","text":"The Ozelot is the weapon carrier of the LeFlaSys light air-defence system, carrying four ready-to-fire Stinger missiles on the stretched Wiesel 2 chassis.","wiki":"https://wiki.warthunder.com/unit/germ_wiesel_2_adwc","src":[]},"modern_aa:germ_flarakpz_1":{"mfr":"Thyssen-Henschel","mfrSource":"wiki","by":"Thyssen-Henschel (Marder chassis); Roland missile by Euromissile (Aérospatiale and MBB)","prod":"1978 – 2005","built":"140 fire units","text":"The Franco-German Roland missile on a Marder chassis gave armoured formations an all-weather short-range missile system with its own search and tracking radars.","wiki":"https://wiki.warthunder.com/unit/germ_flarakpz_1","src":[]},"modern_aa:germ_flarakrad":{"mfr":"MAN","mfrSource":"wiki","by":"MAN (8×8 truck); Roland missile by Euromissile","prod":"mid-1980s – 2005","built":"95","text":"A Roland system in a shelter on a MAN 8×8 truck, used to defend airfields and other key sites.","wiki":"https://wiki.warthunder.com/unit/germ_flarakrad","src":[]},"modern_aa:germ_iris_slm_fcs":{"mfr":"Diehl Defence","mfrSource":"historical","by":"Diehl Defence; TRML-4D radar by Hensoldt","prod":"Bundeswehr from 2024","built":"6 fire units ordered (2023)","text":"The sensor and command part of the IRIS-T SLM system. The system first fought in Ukraine from October 2022; the Bundeswehr received its first fire unit in 2024.","wiki":"https://wiki.warthunder.com/unit/germ_iris_slm_fcs","src":[]},"modern_aa:germ_iris_slm_launcher":{"mfr":"Diehl Defence","mfrSource":"historical","by":"Diehl Defence; MAN SX45 truck","prod":"Bundeswehr from 2024","built":"6 fire units ordered (2023)","text":"The launcher carries eight IRIS-T SL missiles, an extended-range version of the IRIS-T air-to-air missile, on a MAN SX45 truck.","wiki":"https://wiki.warthunder.com/unit/germ_iris_slm_launcher","src":[]},"leopard2:germ_leopard_2a4":{"mfr":"Krauss-Maffei","mfrSource":"wiki","by":"Krauss-Maffei and MaK","prod":"1985 – 1992","built":"2,125 Leopard 2 for Germany (all versions)","text":"The Leopard 2 entered service in 1979 with a 120 mm smoothbore gun, composite armour and a 1,500 PS engine. The 2A4, with digital fire control and an automatic fire-suppression system, became the most widely exported Western tank after the Cold War.","wiki":"https://wiki.warthunder.com/unit/germ_leopard_2a4","src":[["Wikipedia · Leopard 2","https://en.wikipedia.org/wiki/Leopard_2"]]},"leopard2:germ_leopard_2a4m_can":{"mfr":"Krauss-Maffei","mfrSource":"wiki","by":"KMW (upgrade)","prod":"from 2010","built":"","text":"Canada bought surplus Dutch Leopard 2A4s in 2007 and upgraded some as 2A4M CAN, with extra armour and improved sights for operations in Afghanistan.","wiki":"https://wiki.warthunder.com/unit/germ_leopard_2a4m_can","src":[["Wikipedia · Leopard 2","https://en.wikipedia.org/wiki/Leopard_2"]]},"leopard2:germ_leopard_2a5":{"mfr":"Krauss-Maffei","mfrSource":"wiki","by":"Krauss-Maffei Wegmann (conversion)","prod":"1995 – 1998","built":"225 (plus 125 more by 2002)","text":"The 2A5 added the arrow-shaped add-on armour to the turret front, electric turret drives and a thermal sight for the commander.","wiki":"https://wiki.warthunder.com/unit/germ_leopard_2a5","src":[["Wikipedia · Leopard 2","https://en.wikipedia.org/wiki/Leopard_2"]]},"leopard2:germ_leopard_2a6":{"mfr":"KMW","mfrSource":"wiki","by":"Krauss-Maffei Wegmann","prod":"2001 – 2005","built":"225","text":"The 2A6 replaced the L/44 gun with the longer Rheinmetall L/55, raising muzzle velocity and penetration.","wiki":"https://wiki.warthunder.com/unit/germ_leopard_2a6","src":[["Wikipedia · Leopard 2","https://en.wikipedia.org/wiki/Leopard_2"]]},"leopard2:germ_leopard_2a5_pso":{"mfr":"Krauss-Maffei","mfrSource":"wiki","by":"Krauss-Maffei Wegmann","prod":"2006","built":"demonstrator","text":"The Peace Support Operations version was aimed at urban fighting: all-round protection, a dozer blade, a remote weapon station and a shorter gun option.","wiki":"https://wiki.warthunder.com/unit/germ_leopard_2a5_pso","src":[["Wikipedia · Leopard 2","https://en.wikipedia.org/wiki/Leopard_2"]]},"leopard2:germ_leopard_2a7v":{"mfr":"KMW","mfrSource":"wiki","by":"Krauss-Maffei Wegmann","prod":"from 2020","built":"","text":"The 2A7V is the current German service version, with improved armour, new sights and the ability to fire programmable ammunition.","wiki":"https://wiki.warthunder.com/unit/germ_leopard_2a7v","src":[["Wikipedia · Leopard 2","https://en.wikipedia.org/wiki/Leopard_2"]]},"leopard2:germ_leopard_2pl":{"mfr":"Bumar-Łabędy / Rheinmetall","mfrSource":"historical","by":"Bumar-Łabędy with Rheinmetall","prod":"contract 2015; deliveries from about 2020","built":"","text":"Poland's upgrade of ex-German Leopard 2A4s, adding new turret armour, modern sights and electric turret drives.","wiki":"https://wiki.warthunder.com/unit/germ_leopard_2pl","src":[["Wikipedia · Leopard 2","https://en.wikipedia.org/wiki/Leopard_2"]]},"puma:germ_schutzenpanzer_puma":{"mfr":"KMW","mfrSource":"wiki","by":"PSM (Krauss-Maffei Wegmann and Rheinmetall)","prod":"in service from 2015","built":"350","text":"The Puma replaced the Marder with heavy modular armour and an unmanned turret with a 30 mm cannon.","wiki":"https://wiki.warthunder.com/unit/germ_schutzenpanzer_puma","src":[["Wikipedia · Puma (IFV)","https://en.wikipedia.org/wiki/Puma_(IFV)"]]},"puma:germ_schutzenpanzer_puma_vjtf":{"mfr":"KMW","mfrSource":"wiki","by":"PSM (Krauss-Maffei Wegmann and Rheinmetall)","prod":"S1 retrofits from 2019","built":"","text":"The S1 (VJTF) standard prepared Pumas for NATO's high-readiness force with improved sights, MELLS missiles and electronics.","wiki":"https://wiki.warthunder.com/unit/germ_schutzenpanzer_puma_vjtf","src":[["Wikipedia · Puma (IFV)","https://en.wikipedia.org/wiki/Puma_(IFV)"]]},"boxer:germ_boxer_swatrinf":{"mfr":"Rheinmetall / Rheinmetall-Borsig","mfrSource":"wiki","by":"ARTEC (KMW and Rheinmetall)","prod":"ordered 2024; first deliveries 2025","built":"","text":"The heavy weapon carrier for German infantry puts the unmanned RCT30 turret of the Puma, with a 30 mm cannon and Spike LR missiles, on the Boxer drive module.","wiki":"https://wiki.warthunder.com/unit/germ_boxer_swatrinf","src":[["Wikipedia · Boxer","https://en.wikipedia.org/wiki/Boxer_(armoured_fighting_vehicle)"]]},"boxer:germ_vilkas":{"mfr":"Rheinmetall / Rheinmetall-Borsig","mfrSource":"wiki","by":"ARTEC (KMW and Rheinmetall); Rafael Samson Mk II turret","prod":"2019 – 2023","built":"91","text":"Lithuania's Boxer infantry fighting vehicle carries an Israeli Samson turret with a 30 mm cannon and Spike-LR missiles.","wiki":"https://wiki.warthunder.com/unit/germ_vilkas","src":[["Wikipedia · Boxer","https://en.wikipedia.org/wiki/Boxer_(armoured_fighting_vehicle)"]]},"proto_modern:germ_boxer_3105":{"mfr":"KMW","mfrSource":"wiki","by":"Boxer chassis with John Cockerill 3105 turret","prod":"turret shown 2016","built":"demonstrator","text":"A Boxer carrying John Cockerill's 3105 turret with a high-pressure 105 mm gun, demonstrated as a wheeled fire-support vehicle.","wiki":"https://wiki.warthunder.com/unit/germ_boxer_3105","src":[]},"proto_modern:germ_embt":{"mfr":"KNDS (KMW and Nexter)","mfrSource":"historical","by":"KNDS (Krauss-Maffei Wegmann and Nexter)","prod":"2018","built":"demonstrator","text":"Shown at Eurosatory 2018 as a sign of German–French cooperation, the EMBT combined a Leopard 2A7 hull with a Leclerc turret.","wiki":"https://wiki.warthunder.com/unit/germ_embt","src":[]},"jagdpanther:jagd":{"mfr":"MIAG","mfrSource":"wiki","by":"MIAG, MNH, MBA","prod":"Jan 1944 – 1945","built":"413","text":"The Jagdpanther put the 8.8 cm PaK 43/3 in a well-sloped casemate on the Panther chassis, combining Panther mobility with the Tiger II's gun. MIAG built most of them.","wiki":"https://wiki.warthunder.com/unit/germ_panzerjager_panther","src":[["Wikipedia · Jagdpanther","https://en.wikipedia.org/wiki/Jagdpanther"]]},"jagdpanther:germ_panzerbefelhswagen_jagdpanther":{"mfr":"MIAG","mfrSource":"wiki","by":"MIAG","prod":"1944 – 1945","built":"","text":"A command version of the Jagdpanther with additional radio equipment.","wiki":"https://wiki.warthunder.com/unit/germ_panzerbefelhswagen_jagdpanther","src":[["Wikipedia · Jagdpanther","https://en.wikipedia.org/wiki/Jagdpanther"]]}};
